// Safe extraction from upstream QC node or directly from Gemini
const reportText =
  $json.final_report_markdown ||
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  $json.text ||
  $('Generate Intelligence Report').first()?.json?.candidates?.[0]?.content?.parts?.[0]?.text ||
  '';

// 1. Dynamic date range (past 7 days up to today)
const now = new Date();
const pastDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const dateOpts = { month: 'short', day: 'numeric', year: 'numeric' };
const startDateStr = pastDate.toLocaleDateString('en-US', dateOpts);
const endDateStr = now.toLocaleDateString('en-US', dateOpts);

const emailSubject =
  ($json.requires_approval ? '[REVIEW] ' : '') +
  `Weekly Cellular IoT Intelligence Briefing: ${startDateStr} – ${endDateStr}`;

// Competitor names from the data (falls back to the old list if unavailable)
let competitorNames = 'Telit Cinterion, Quectel, Semtech';
try {
  const names = [...new Set(
    $('Filter & Group by Company').all().map(i => i.json.company).filter(Boolean)
  )];
  if (names.length) competitorNames = names.join(', ');
} catch (e) {}

// 2. Extract key highlights from the Executive Summary for the teaser box
let teaserHtml = '<li>See the attached briefing for this week\'s key competitor moves.</li>';

const execSection = reportText.match(
  /Executive Summary[\s\S]*?(?=\n\s*(?:#+\s*)?(?:\*\*)?2\.\s*Competitor|$)/i
);

if (execSection) {
  const bullets = execSection[0]
    .split('\n')
    .filter(l => /^\s*[-*•]\s+/.test(l))                 // real bullets only (not **bold** lines)
    .slice(0, 3)
    .map(b => b
      .replace(/^\s*[-*•]\s+/, '')
      .replace(/\*\*(.*?)\*\*/g, '$1')                   // strip bold markers
      .replace(/\[(.*?)\]\((.*?)\)/g, '$1')              // strip markdown links
      .trim());
  if (bullets.length > 0) {
    teaserHtml = bullets.map(b => `<li style="margin-bottom: 6px;">${b}</li>`).join('');
  }
}

// 3. Convert Markdown syntax into clean HTML for email preview & PDF
const formatMarkdown = (md) => {
  if (!md) return '<p><em>No briefing content available.</em></p>';
  return md
    .replace(/^# (.*$)/gim, '<h1 style="color: #1a365d; font-size: 20px; border-bottom: 2px solid #cbd5e0; padding-bottom: 6px; margin-top: 20px;">$1</h1>')
    .replace(/^## (.*$)/gim, '<h2 style="color: #2b6cb0; font-size: 16px; margin-top: 18px; margin-bottom: 8px; border-left: 3px solid #3182ce; padding-left: 8px;">$1</h2>')
    .replace(/^### (.*$)/gim, '<h3 style="color: #2d3748; font-size: 14px; margin-top: 14px; margin-bottom: 4px;">$1</h3>')
    .replace(/^\- (.*$)/gim, '<li style="margin-bottom: 5px; color: #4a5568; font-size: 13px; line-height: 1.5;">$1</li>')
    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
    .replace(/\[(.*?)\]\((.*?)\)/gim, '<a href="$2" style="color: #3182ce; text-decoration: underline;">$1</a>')
    .replace(/\n\n/gim, '<p style="margin: 8px 0; color: #4a5568; line-height: 1.5; font-size: 13px;"></p>');
};

const reportHtmlBody = formatMarkdown(reportText);

// 4. Standalone printable HTML document for PDFShift
const pdfDocumentHtml = `
