  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #2d3748; line-height: 1.5; font-size: 12px; }
  h1 { color: #1a365d; font-size: 18px; border-bottom: 2px solid #cbd5e0; padding-bottom: 6px; margin-bottom: 12px; }
  h2 { color: #2b6cb0; font-size: 14px; margin-top: 16px; margin-bottom: 6px; border-left: 3px solid #3182ce; padding-left: 6px; }
  h3 { color: #2d3748; font-size: 13px; margin-top: 10px; margin-bottom: 2px; }
  ul { padding-left: 18px; margin-top: 4px; }
  li { margin-bottom: 4px; }
  p { margin: 6px 0; }
  a { color: #3182ce; text-decoration: underline; }
  .header-box { background: #ebf8ff; border-left: 4px solid #3182ce; padding: 8px 12px; margin-bottom: 15px; font-size: 11px; }
</style>
</head>
<body>
